INSERT OR IGNORE INTO tags (name) SELECT 'twitter' WHERE EXISTS (SELECT 1 FROM items WHERE kind = 'link' AND (lower(url) LIKE 'https://x.com/%' OR lower(url) LIKE 'http://x.com/%' OR lower(url) LIKE 'https://www.x.com/%' OR lower(url) LIKE 'http://www.x.com/%' OR lower(url) LIKE 'https://mobile.x.com/%' OR lower(url) LIKE 'http://mobile.x.com/%' OR lower(url) LIKE 'https://twitter.com/%' OR lower(url) LIKE 'http://twitter.com/%' OR lower(url) LIKE 'https://www.twitter.com/%' OR lower(url) LIKE 'http://www.twitter.com/%' OR lower(url) LIKE 'https://mobile.twitter.com/%' OR lower(url) LIKE 'http://mobile.twitter.com/%' OR lower(url) LIKE 'https://m.twitter.com/%' OR lower(url) LIKE 'http://m.twitter.com/%'));
INSERT OR IGNORE INTO item_tags (item_id, tag) SELECT id, 'twitter' FROM items WHERE kind = 'link' AND (lower(url) LIKE 'https://x.com/%' OR lower(url) LIKE 'http://x.com/%' OR lower(url) LIKE 'https://www.x.com/%' OR lower(url) LIKE 'http://www.x.com/%' OR lower(url) LIKE 'https://mobile.x.com/%' OR lower(url) LIKE 'http://mobile.x.com/%' OR lower(url) LIKE 'https://twitter.com/%' OR lower(url) LIKE 'http://twitter.com/%' OR lower(url) LIKE 'https://www.twitter.com/%' OR lower(url) LIKE 'http://www.twitter.com/%' OR lower(url) LIKE 'https://mobile.twitter.com/%' OR lower(url) LIKE 'http://mobile.twitter.com/%' OR lower(url) LIKE 'https://m.twitter.com/%' OR lower(url) LIKE 'http://m.twitter.com/%');
